# ============================================================
# OPSYN DESIGN HYDRATOR — app/modules/design/hydrator.py
#
# Database rows → FTTx engine domain objects (Network GIS plan §3.6), so the
# engine's own BOQ and rules run on ANY design — generated by the engine
# (Phase 5) or drawn by hand (Phase 6) — exactly as they do inside a run.
#
#   net_assets FDT       → FDT, owning the FATs it feeds (net_connections)
#   net_assets FAT       → FAT: road = nearest design road; customers from
#                          used_capacity / attributes; wing, sequence and
#                          parent FDT from connections or attributes
#   net_assets CLOSURE   → DomeClosure, with the FDTs it feeds
#   net_cables           → CableSegment, grouped as the engine groups them:
#                          BOX_TO_BOX/DISTRIBUTION → b2b, DROP → b2c,
#                          CLOSURE_FDT → closure, FEEDER/PICKUP → pickup
#   design_inputs homepass → Homepass on its nearest road
#
# Geometry is projected into the context's UTM zone; lengths come from the
# database (length_m, computed from the stored geometry).
# ============================================================

from __future__ import annotations

import json
import uuid
from dataclasses import dataclass, field
from typing import Any

from sqlalchemy import text
from sqlalchemy.ext.asyncio import AsyncSession

from app.modules.design.engine_bridge import HOMEPASS_COUNT_FIELD, EngineContext
from app.modules.fttx_designer.engine.domain import FAT, FDT, CableSegment, DomeClosure, Homepass
from app.modules.fttx_designer.engine.geometry_compat import QgsGeometry

CABLE_GROUP = {
    "BOX_TO_BOX": "b2b", "DISTRIBUTION": "b2b", "DROP": "b2c",
    "CLOSURE_FDT": "closure", "FEEDER": "pickup", "PICKUP": "pickup",
}


@dataclass
class Hydrated:
    fdts: list[FDT] = field(default_factory=list)
    fats: list[FAT] = field(default_factory=list)
    closures: list[DomeClosure] = field(default_factory=list)
    homepasses: list[Homepass] = field(default_factory=list)
    b2b_cables: list[CableSegment] = field(default_factory=list)
    b2c_cables: list[CableSegment] = field(default_factory=list)
    closure_cables: list[CableSegment] = field(default_factory=list)
    pickup_cables: list[CableSegment] = field(default_factory=list)
    # asset / cable id → engine object name, for mapping findings back
    names: dict[str, str] = field(default_factory=dict)


def _int(v: Any, default: int = 0) -> int:
    try:
        return int(float(v))
    except (TypeError, ValueError):
        return default


async def load_working_set(db: AsyncSession, tid: uuid.UUID, design_id: uuid.UUID) -> dict[str, list[Any]]:
    p = {"d": design_id, "tid": tid}
    assets = (await db.execute(text("""
        SELECT id, asset_code, asset_type, capacity, used_capacity, attributes,
               ST_X(ST_PointOnSurface(geom)) AS lng, ST_Y(ST_PointOnSurface(geom)) AS lat
        FROM net_assets WHERE design_id = :d AND tenant_id = :tid AND deleted_at IS NULL
    """), p)).all()
    cables = (await db.execute(text("""
        SELECT c.id, c.asset_code, c.cable_category, c.length_m::float8 AS length_m, c.fiber_count,
               ST_AsGeoJSON(c.geom, 7) AS g, s.asset_code AS src, d.asset_code AS dst
        FROM net_cables c
        LEFT JOIN net_assets s ON s.id = c.source_asset_id
        LEFT JOIN net_assets d ON d.id = c.dest_asset_id
        WHERE c.design_id = :d AND c.tenant_id = :tid AND c.deleted_at IS NULL
    """), p)).all()
    links = (await db.execute(text("""
        SELECT k.source_asset_id, k.dest_asset_id FROM net_connections k
        WHERE k.design_id = :d AND k.tenant_id = :tid AND k.deleted_at IS NULL
    """), p)).all()
    return {"assets": assets, "cables": cables, "links": links}


def hydrate(ctx: EngineContext, ws: dict[str, list[Any]], homepass_fc: dict[str, Any] | None) -> Hydrated:
    h = Hydrated()
    by_id = {r.id: r for r in ws["assets"]}
    children: dict[Any, list[Any]] = {}
    parent_of: dict[Any, Any] = {}
    for link in ws["links"]:
        children.setdefault(link.source_asset_id, []).append(link.dest_asset_id)
        parent_of[link.dest_asset_id] = link.source_asset_id
    fdt_by_code = {r.asset_code.lower(): r for r in ws["assets"] if r.asset_type == "FDT"}

    fat_objs: dict[Any, FAT] = {}
    for r in ws["assets"]:
        if r.asset_type != "FAT":
            continue
        at = r.attributes or {}
        pt = ctx.to_utm(r.lng, r.lat)
        parent = by_id.get(parent_of.get(r.id))
        if parent is None or parent.asset_type != "FDT":
            parent = fdt_by_code.get(str(at.get("parent_fdt_code") or "").lower())
        fat = FAT(
            name=r.asset_code, geometry=pt, road_id=ctx.nearest_road_id(pt) or -1,
            total_customers=_int(r.used_capacity if r.used_capacity is not None else at.get("customers")),
            cascade_order=_int(at.get("sequence")), from_device=parent.asset_code if parent else "",
            to_device="", wing=str(at.get("wing") or "A"),
            parent_fdt=parent.asset_code if parent else "", splitter_type=str(at.get("engine_splitter_type") or at.get("splitter_ratio") or ""),
            snapped_geometry=pt, structure_name=str(at.get("structure_name") or ""),
        )
        fat_objs[r.id] = fat
        h.fats.append(fat)
        h.names[str(r.id)] = fat.name

    fdt_objs: dict[Any, FDT] = {}
    for r in ws["assets"]:
        if r.asset_type != "FDT":
            continue
        own = [f for f in h.fats if f.parent_fdt == r.asset_code]
        pt = ctx.to_utm(r.lng, r.lat)
        fdt = FDT(
            name=r.asset_code, geometry=pt, total_customers=sum(f.total_customers for f in own),
            total_fat=len(own), wing_a_count=sum(f.wing == "A" for f in own),
            wing_b_count=sum(f.wing == "B" for f in own), wing_c_count=sum(f.wing == "C" for f in own),
            wing_d_count=sum(f.wing == "D" for f in own), fats=own, snapped_geometry=pt,
            primary_road_id=ctx.nearest_road_id(pt),
        )
        fdt_objs[r.id] = fdt
        h.fdts.append(fdt)
        h.names[str(r.id)] = fdt.name

    for r in ws["assets"]:
        if r.asset_type != "CLOSURE":
            continue
        fed = [fdt_objs[c] for c in children.get(r.id, []) if c in fdt_objs]
        closure = DomeClosure(name=r.asset_code, geometry=ctx.to_utm(r.lng, r.lat), fdts=fed, total_fdt=len(fed),
                              feed_capacity=_int(r.capacity, 24))
        h.closures.append(closure)
        h.names[str(r.id)] = closure.name

    for c in ws["cables"]:
        coords = json.loads(c.g)["coordinates"]
        geom = QgsGeometry.fromPolylineXY([ctx.to_utm(x, y) for x, y in coords])
        seg = CableSegment(name=c.asset_code, start_device=c.src or "", end_device=c.dst or "",
                           geometry=geom, length=float(c.length_m or 0.0),
                           fdt_id=c.src if c.cable_category in ("BOX_TO_BOX", "DISTRIBUTION") else "",
                           core_info={"cable_capacity": c.fiber_count or ""})
        getattr(h, f"{CABLE_GROUP.get(c.cable_category, 'b2b')}_cables").append(seg)
        h.names[str(c.id)] = seg.name

    for i, f in enumerate((homepass_fc or {}).get("features", [])):
        lng, lat = f["geometry"]["coordinates"][:2]
        pt = ctx.to_utm(lng, lat)
        h.homepasses.append(Homepass(fid=i, geometry=pt,
                                     customer_count=_int(f["properties"].get(HOMEPASS_COUNT_FIELD), 1),
                                     road_id=ctx.nearest_road_id(pt)))
    return h

